def criar_unidades_demo(apps, schema_editor):
    Carro = apps.get_model('locadora', 'Carro')
    banco = schema_editor.connection.alias

    for indice, (modelo, diaria) in enumerate(CARROS_DEMONSTRACAO, start=1):
        if Carro.objects.using(banco).filter(modelo=modelo).exists():
            continue

        placa = f'DEM0{chr(ord("A") + indice - 1)}01'
        chassi = f'D3M{indice:014d}'
        if (
            Carro.objects.using(banco).filter(placa=placa).exists()
            or Carro.objects.using(banco).filter(chassi=chassi).exists()
        ):
            raise RuntimeError(f'Identificador de demonstração já cadastrado para {modelo}.')

        Carro.objects.using(banco).create(
            modelo=modelo,
            placa=placa,
            chassi=chassi,
            ano=2025,
            diaria=diaria,
            status='disponivel',
            eh_demonstracao=True,
        )


def remover_unidades_demo(apps, schema_editor):
    Carro = apps.get_model('locadora', 'Carro')
    banco = schema_editor.connection.alias
    placas = [
        f'DEM0{chr(ord("A") + indice - 1)}01'
        for indice in range(1, len(CARROS_DEMONSTRACAO) + 1)
    ]
    Carro.objects.using(banco).filter(
        placa__in=placas,
        eh_demonstracao=True,
    ).delete()


